      "edits": {
        "type": "array",
        "maxItems": 32,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "path",
            "content"
          ],
          "properties": {
            "path": {
              "type": "string"
            },
            "content": {
              "type": "string"
            }
          }
        }
      }
    }
  },
  "baseFiles": [
    {
      "path": "openclaw_runtime/src/agents/workspace-external-write-provenance-policy.ts",
      "content": null,
      "missing": true
    }
  ]
}

