export const WORKSPACE_EXTERNAL_WRITE_PROVENANCES = [
  "trusted",
  "operator",
  "external",
  "derived",
  "invalid",
  "missing",
] as const;

export type WorkspaceExternalWriteProvenance =
  (typeof WORKSPACE_EXTERNAL_WRITE_PROVENANCES)[number];

export interface WorkspaceExternalWriteProvenancePolicyInput {
  provenance?: WorkspaceExternalWriteProvenance | null;
}

export type WorkspaceExternalWriteProvenanceDecision =
  | { allowed: true; provenance: "trusted" | "operator" }
  | {
      allowed: false;
      provenance: WorkspaceExternalWriteProvenance | "missing";
      reason: "untrusted-provenance" | "missing-provenance";
    };

function normalizeProvenance(
  input:
    | WorkspaceExternalWriteProvenance
    | WorkspaceExternalWriteProvenancePolicyInput
    | null
    | undefined,
): WorkspaceExternalWriteProvenance | "missing" {
  if (input === null || input === undefined) {
    return "missing";
  }

  const provenance =
    typeof input === "string" ? input : input.provenance ?? "missing";

  if (
    provenance === "trusted" ||
    provenance === "operator" ||
    provenance === "external" ||
    provenance === "derived" ||
    provenance === "invalid" ||
    provenance === "missing"
  ) {
    return provenance;
  }

  return "invalid";
}

export function evaluateWorkspaceExternalWriteProvenance(
  input:
    | WorkspaceExternalWriteProvenance
    | WorkspaceExternalWriteProvenancePolicyInput
    | null
    | undefined,
): WorkspaceExternalWriteProvenanceDecision {
  const provenance = normalizeProvenance(input);

  if (provenance === "trusted" || provenance === "operator") {
    return { allowed: true, provenance };
  }

  return {
    allowed: false,
    provenance,
    reason: provenance === "missing" ? "missing-provenance" : "untrusted-provenance",
  };
}

export function isWorkspaceExternalWriteAllowed(
  input:
    | WorkspaceExternalWriteProvenance
    | WorkspaceExternalWriteProvenancePolicyInput
    | null
    | undefined,
): boolean {
  return evaluateWorkspaceExternalWriteProvenance(input).allowed;
}

export function assertWorkspaceExternalWriteAllowed(
  input:
    | WorkspaceExternalWriteProvenance
    | WorkspaceExternalWriteProvenancePolicyInput
    | null
    | undefined,
): void {
  const decision = evaluateWorkspaceExternalWriteProvenance(input);
  if (!decision.allowed) {
    throw new Error(
      `Workspace-external write rejected: ${decision.reason} (${decision.provenance})`,
    );
  }
}

